function sdAes(plain) {
    try {
        var cipher = java.createSymmetricCrypto(
            "AES/CBC/PKCS7Padding",
            java.strToBytes('a2OyzjKv9Jwxr8182c1PcQW27MTayx76'),
            java.strToBytes('1102684108433530')
        );
        return cipher.encryptBase64(plain).toString();
    } catch (e) {
        var crypto = require('crypto');
        var key = Buffer.from('a2OyzjKv9Jwxr8182c1PcQW27MTayx76', 'utf8');
        var iv = Buffer.from('1102684108433530', 'utf8');
        var c = crypto.createCipheriv('aes-256-cbc', key, iv);
        var out = Buffer.concat([c.update(Buffer.from(plain, 'utf8')), c.final()]);
        return out.toString('base64');
    }
}

function chapterPageUrl(id, page, pages) {
    var data = encodeURIComponent(sdAes(JSON.stringify({ id: id, page: page })));
    var url = 'https://www.shoudaxs.com/index.php?action=loadChapterPage&sdid=' + id
        + '&sdp=' + pages + '&sdpn=' + page;
    return url + ',' + JSON.stringify({
        method: 'POST',
        body: 'data=' + data,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
            'Origin': 'https://www.shoudaxs.com',
            'Referer': 'https://www.shoudaxs.com/book/' + id + '.html'
        }
    });
}

